INSERT INTO `about_us` (`id`, `content`, `created_at`, `updated_at`) VALUES
(1, '<h1>Về Chúng Tôi - King Express Travel</h1><p>Đây là nội dung giới thiệu mặc định về công ty. Bạn có thể chỉnh sửa nội dung này trong trang quản trị.</p>', '2025-09-04 09:32:18', '2025-09-04 09:32:18');
