INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(1, 'HANOI001', 'Tour du lịch Hà Nội 1 ngày - HANOI001', '1 ngày', 'Hà Nội', 100, 700000, 550000, 350000, NULL, 'Ô tô', 'Hà Nội – thủ đô ngàn năm văn hiến luôn cuốn hút du khách bởi nét cổ kính, yên bình lạ kỳ. Đến với Tour du lịch Hà Nội 1 ngày, quý khách sẽ được đến các điểm thăm quan hấp dẫn nhất và danh thắng nổi tiếng ở Hà Nội như: Văn miếu Quốc Tử Giám – biểu trưng của một thủ đô giàu truyền thống hiếu học, Bảo tàng dân tộc học – nơi lưu giữ bản sắc văn hóa của 54 dân tộc anh em, lăng chủ tịch Hồ Chí Minh – nơi an nghỉ ngàn thu của Bác Hồ kính yêu…', NULL, 1, '[{\"title\":\"S\\u00c1NG: Ch\\u00f9a Tr\\u1ea5n Qu\\u1ed1c \\u2013 L\\u0103ng B\\u00e1c \\u2013 B\\u1ea3o t\\u00e0ng D\\u00e2n t\\u1ed9c h\\u1ecdc \\/ B\\u1ea3o t\\u00e0ng Ph\\u1ee5 n\\u1eef\",\"content\":\"<p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">08h00-09h00<\\/strong>: Xe v\\u00e0 h\\u01b0\\u1edbng d\\u1eabn vi\\u00ean \\u0111\\u00f3n qu\\u00fd kh\\u00e1ch t\\u1ea1i kh\\u00e1ch s\\u1ea1n khu v\\u1ef1c ph\\u1ed1 C\\u1ed5 v\\u00e0 Nh\\u00e0 h\\u00e1t l\\u1edbn b\\u1eaft \\u0111\\u1ea7u cho chuy\\u1ebfn th\\u0103m quan th\\u1ee7 \\u0111\\u00f4 H\\u00e0 N\\u1ed9i (Hanoi Citytour). Bu\\u1ed5i s\\u00e1ng, Qu\\u00fd kh\\u00e1ch th\\u0103m quan c\\u00e1c \\u0111i\\u1ec3m:<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">\\u2713<\\/strong><\\/span><\\/span><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"> 9h1<\\/strong><\\/span><\\/span><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">5:Ch\\u00f9a Tr\\u1ea5n Qu\\u1ed1c <\\/strong>\\u2013 ng\\u00f4i ch\\u00f9a n\\u1eb1m tr\\u00ean m\\u1ed9t h\\u00f2n \\u0111\\u1ea3o ph\\u00eda \\u0110\\u00f4ng c\\u1ee7a H\\u1ed3 T\\u00e2y (qu\\u1eadn T\\u00e2y H\\u1ed3). Ch\\u00f9a c\\u00f3 l\\u1ecbch s\\u1eed g\\u1ea7n 1500 n\\u0103m, \\u0111\\u01b0\\u1ee3c coi l\\u00e0 l\\u00e2u \\u0111\\u1eddi nh\\u1ea5t \\u1edf Th\\u0103ng Long \\u2013 H\\u00e0 N\\u1ed9i. Ki\\u1ebfn tr\\u00fac ch\\u00f9a c\\u00f3 s\\u1ef1 k\\u1ebft h\\u1ee3p h\\u00e0i ho\\u00e0 gi\\u1eefa t\\u00ednh uy nghi\\u00eam, c\\u1ed5 k\\u00ednh v\\u1edbi c\\u1ea3nh quan thanh nh\\u00e3 gi\\u1eefa n\\u1ec1n t\\u0129nh l\\u1eb7ng c\\u1ee7a m\\u1ed9t h\\u1ed3 n\\u01b0\\u1edbc m\\u00eanh mang. L\\u00e0 trung t\\u00e2m Ph\\u1eadt gi\\u00e1o c\\u1ee7a kinh th\\u00e0nh Th\\u0103ng Long v\\u00e0o th\\u1eddi nh\\u00e0 L\\u00fd v\\u00e0 nh\\u00e0 Tr\\u1ea7n. Ta\\u0323i \\u0111\\u00e2y, quy\\u0301 kha\\u0301ch se\\u0303 co\\u0301 c\\u01a1 h\\u00f4\\u0323i ng\\u0103\\u0301m nhi\\u0300n m\\u00f4\\u0323t trong nh\\u01b0\\u0303ng c\\u00e2y B\\u00f4\\u0300 \\u0110\\u00ea\\u0300 l\\u01a1\\u0301n nh\\u00e2\\u0301t Vi\\u00ea\\u0323t Nam.<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">\\u2713 10h00: \\u0110o\\u00e0n tham quan Khu di t\\u00edch H\\u1ed3 Ch\\u00ed Minh <\\/strong>\\u0111\\u01b0\\u1ee3c kh\\u00e1nh th\\u00e0nh n\\u0103m 1975, m\\u1ed9t ph\\u1ee9c h\\u1ee3p bao g\\u1ed3m: L\\u0103ng Ch\\u1ee7 t\\u1ecbch H\\u1ed3 Ch\\u00ed Minh, Qu\\u1ea3ng Tr\\u01b0\\u1eddng Ba \\u0110\\u00ecnh, Ph\\u1ee7 Ch\\u1ee7 T\\u1ecbch, Khu nh\\u00e0 s\\u00e0n, Ao C\\u00e1, Ch\\u00f9a M\\u1ed9t C\\u1ed9t\\u2026&nbsp;<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">C\\u00e1c \\u0111i\\u1ec3m tham quan kh\\u00e1c trong khu v\\u1ef1c nh\\u01b0 Qu\\u1ea3ng tr\\u01b0\\u1eddng Ba \\u0110\\u00ecnh, Ph\\u1ee7 Ch\\u1ee7 t\\u1ecbch, Nh\\u00e0 s\\u00e0n B\\u00e1c H\\u1ed3 v\\u1eabn c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c s\\u1eafp x\\u1ebfp tham quan b\\u00ecnh th\\u01b0\\u1eddng<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">+ Qu\\u1ea3ng tr\\u01b0\\u1eddng Ba \\u0110\\u00ecnh- <\\/strong>n\\u01a1i di\\u1ec5n ra s\\u1ef1 ki\\u1ec7n tr\\u1ecdng \\u0111\\u1ea1i nh\\u1ea5t c\\u1ee7a d\\u00e2n t\\u1ed9c Vi\\u1ec7t Nam v\\u00e0o ng\\u00e0y 2\\/9\\/1945, Ch\\u1ee7 t\\u1ecbch H\\u1ed3 Ch\\u00ed Minh \\u0111\\u00e3 \\u0111\\u1ecdc B\\u1ea3n Tuy\\u00ean ng\\u00f4n \\u0110\\u1ed9c l\\u1eadp khai sinh ra n\\u01b0\\u1edbc Vi\\u1ec7t Nam D\\u00e2n ch\\u1ee7 C\\u1ed9ng h\\u00f2a.<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-st