bkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– </span></span><a style=\"box-sizing:border-box;color:rgb(16, 90, 142);margin:0px;padding:0px;text-decoration:none;\" href=\"https://thesinhtour.com/lich-bao-tri-lang-bac-2025/\" target=\"_blank\" rel=\"noopener\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">Lịch Bảo Trì Lăng Bác 2025</strong></span></span></a><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">: <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\" data-start=\"1594\" data-end=\"1623\">Lăng Chủ tịch Hồ Chí Minh</strong> sẽ <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\" data-start=\"1627\" data-end=\"1681\">tạm dừng đón khách viếng từ ngày 2/6 đến 31/7/2025</strong> để phục vụ công tác bảo trì thường niên. Du khách có nhu cầu viếng thăm Lăng Bác nên lên kế hoạch từ ngày <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\" data-start=\"1788\" data-end=\"1807\">2/8/2025 trở đi</strong> để không ảnh hưởng đến lịch trình du lịch.&nbsp;Các điểm tham quan khác trong khu vực như Quảng trường Ba Đình, Phủ Chủ tịch, Nhà sàn Bác Hồ vẫn có thể được sắp xếp tham quan bình thường</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– </span><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Lăng Bác đóng cửa Thứ 2 &amp; Thứ 6 nên du khách sẽ không được vào lăng viếng Bác. Các điểm khác trong quần thể Lăng vẫn tham quan bình thường.</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Bảo Tàng Dân Tộc Học đóng cửa vào thứ 2 → thăm Bảo Tàng Phụ Nữ thay thế.</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Khách không ăn trưa (-100.000đ), giờ đón khách không ăn trưa Tour nửa ngày buổi chiều: từ 13h30</span></i></em></span></p><div class=\"table-responsive\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;overflow-x:auto;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><figure class=\"table\"><table style=\"border-collapse:collapse;box-sizing:border-box;margin:0px;padding:0px;width:809.6px;\" border=\".\"><tbody style=\"box-sizing:border-box;margin:0px;padding:0px;\"><tr style=\"box-sizing:border-box;margin:0px;padding:0px;\"><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;margin:0px;padding:0.5em;width:484.788px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">BAO GỒM</strong></span></span></p></td><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;margin:0px;padding:0.5em;width:324.013px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">KHÔNG BAO GỒM</strong></span></span></p></td></tr><tr style=\"box-sizing:border-box;margin:0px;padding:0px;\"><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;margin:0px;padding:0.5em;width:484.788px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">–</span><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"> Xe ô tô máy lạnh / sang trọng trong suốt hành trình</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– 01 chai nước / khách trên xe</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Vé vào cửa 01 lần tại tất cả các điểm thăm quan có trong lịch trình</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– HDV song ngữ Tiếng Anh/Tiếng Việt</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– 1 bữa ăn trưa tại nhà hàng</span></i></em></span></p></td><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;margin:0px;padding:0.5em;width:324.013px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Hóa đơn GTGT</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Đồ uống trong bữa ăn trưa</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Tip cho HDV, Lái Xe</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Xích lô, xem rối nước</span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\">– Chi phí cá nhân hoặc bất kỳ chi phí gì không được đề cập ở mục BAO GỒM.</span></i></em></span></p></td></tr></tbody></table></figure></div>', '<p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Lăng Bác mở cửa chỉ buổi sáng các ngày trong tuần (trừ thứ 2 và thứ 6)</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Lăng Bác đóng cửa 2 tháng để bảo trì (bắt đầu từ <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">2/6/2025 – 31/7/2025</strong>)</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Nên ăn mặc chỉnh tề khi tham gia tour ( áo phải có tay, quần áo dài ít nhất tới đầu gối)</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Nên mang theo tiền mặt, máy ảnh, kem chống nắng, ô dù, mũ nón khi tham gia tour …(tùy thuộc thời tiết)</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Chương trình cố định nhưng thứ tự các điểm thăm quan có thể bị thay đổi do nguyên nhân khách quan &amp; sự sắp xếp của hướng dẫn viên.</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Tour có thể kết thúc sớm hơn hoặc muộn hơn so với lịch trình do tốc độ thăm quan của đoàn.</span></span></p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Trải nghiệm một ngày trọn vẹn tại Hà Nội – thủ đô ngàn năm văn hiến với hành trình hấp dẫn, dịch vụ chuyên nghiệp và hướng dẫn viên tận tâm.</span></span></p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Đặt ngay để không bỏ lỡ cơ hội khám phá Hà Nội đầy màu sắc!&nbsp;</span></span></p>', NULL, '2025-09-04 09:48:19', '2025-09-04 10:07:48');
INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(3, 'HANOI002', 'Tour du lịch Hà Nội 1 ngày - HANOI002', '1 ngày', 'Hà Nội', 100, 700000, 550000, 350000, NULL, 'Ô tô', 'Tour Hà Nội 1 ngày là lựa chọn hoàn hảo để bạn trải nghiệm những địa danh lịch sử – văn hóa nổi tiếng, thưởng thức ẩm thực đặc trưng và khám phá nét đẹp truyền thống của thủ đô Việt Nam. Hành trình kết hợp giữa tham quan di tích, trải nghiệm làng nghề, và thưởng thức đặc sản Hà Nội sẽ mang lại cho bạn một ngày đáng nhớ.', NULL, 1, '[{\"title\":\"S\\u00c1NG: Nh\\u00e0 t\\u00f9 H\\u1ecfa L\\u00f2 \\u2013 L\\u0103ng Ch\\u1ee7 t\\u1ecbch H\\u1ed3 Ch\\u00ed Minh \\u2013 Ph\\u1ed1 Cafe \\u0110\\u01b0\\u1eddng T\\u00e0u\",\"content\":\"<h3 style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\" data-start=\\\"696\\\" data-end=\\\"717\\\">07:30 \\u2013 \\u0110\\u00f3n Kh\\u00e1ch<\\/h3><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\" data-start=\\\"718\\\" data-end=\\\"882\\\">H\\u01b0\\u1edbng d\\u1eabn vi\\u00ean v\\u00e0 xe <strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\" data-start=\\\"739\\\" data-end=\\\"759\\\">Limousi