spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"3007\" data-end=\"3037\">địa danh lịch sử – văn hóa</strong><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"> nổi tiếng</span></span><br><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">🍜 </span></span><strong style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"3055\" data-end=\"3085\">Thưởng thức đặc sản Hà Nội</strong><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"> chuẩn vị</span></span><br><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">🏺 Trải nghiệm </span></span><strong style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"3114\" data-end=\"3152\">làm gốm tại làng nghề truyền thống</strong><br><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">☕ Thư giãn với </span></span><strong style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-start=\"3172\" data-end=\"3185\">trà chiều</strong><span style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"> đậm chất Bắc Bộ</span></span></p>', '2025-09-04 09:48:19', '2025-09-04 10:07:39');
INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(4, 'CHUAHUONG001', 'Tour Chùa Hương 1 ngày', '1 ngày', 'Hà Nội', 100, 890000, 890000, 890000, 890000, 'Ô tô', 'Chùa Hương cách Hà Nội 62km về phía Tây Nam, thuộc địa bàn xã Hương Sơn – huyện Mỹ Đức (TP.Hà Nội). Không chỉ đẹp và lãng mạn, Tour chùa Hương 1 ngày còn nổi tiếng là miền đất Phật thu hút hàng triệu du khách trong và ngoài nước đến hành hương, thưởng lãm. Ngồi trên đò, ngược dòng Yến Vỹ, mùi hương đất trời, cỏ cây bảng lảng trong sương khói. Chùa lại nằm sâu trong núi, ẩn hiện mơ màng trong mây, khiến du khách như lạc vào chốn bồng lai tiên cảnh.', '<div class=\"chitietsanpham clear contenhang\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;clear:both;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 30px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" id=\"single_prod_introduce\"><p style=\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Núi ở<strong style=\"box-sizing:border-box;margin:0px;padding:0px;\"> tour&nbsp;</strong></span><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">chùa Hương 1 ngày</strong></span></i></em><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">&nbsp;không hùng vĩ chất ngất như nhiều dãy núi khác ở Việt Nam, nhưng lại có vẻ đẹp kỳ thú với gắn liền với đời sống hiện thực như: Núi ba đài rượu, núi con trăn, núi mâm xôi, núi con gà, núi voi, núi đổi chèo…</span></span></p><div class=\"table-responsive\" style=\"box-sizing:border-box;margin:0px;overflow-x:auto;padding:0px;\"><figure class=\"table\"><table style=\"border-collapse:collapse;box-sizing:border-box;height:278px;margin:0px;padding:0px;width:809.6px;\"><tbody style=\"box-sizing:border-box;margin:0px;padding:0px;\"><tr style=\"box-sizing:border-box;height:278px;margin:0px;padding:0px;\"><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;height:278px;margin:0px;padding:0.5em;text-align:center;width:404.4px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><img class=\"wp-image-467 aligncenter perfmatters-lazy entered pmloaded\" style=\"animation:500ms ease 0s 1 normal none running pmFadeIn;border-style:none;box-sizing:border-box;display:block;height:auto;margin:0px auto;max-width:100%;padding:0px;\" src=\"https://thesinhtour.com/wp-content/uploads/2015/01/tour-chua-huong.jpg\" alt=\"tour chùa hương\" decoding=\"async\" title=\"Tour chùa hương\" width=\"399\" height=\"271\" data-src=\"https://thesinhtour.com/wp-content/uploads/2015/01/tour-chua-huong.jpg\" data-ll-status=\"loaded\"></span></span></p></td><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;height:278px;margin:0px;padding:0.5em;width:404.4px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><img class=\"wp-image-471 aligncenter perfmatters-lazy entered pmloaded\" style=\"animation:500ms ease 0s 1 normal none running pmFadeIn;border-style:none;box-sizing:border-box;display:block;height:auto;margin:0px auto;max-width:100%;padding:0px;\" src=\"https://thesinhtour.com/wp-content/uploads/2015/01/cap-treo-chua-huong-e1421917727175.jpg\" alt=\"tour du lịch chùa hương cáp treo\" decoding=\"async\" title=\"Cáp treo Chùa Hương\" width=\"413\" height=\"268\" data-src=\"https://thesinhtour.com/wp-content/uploads/2015/01/cap-treo-chua-huong-e1421917727175.jpg\" data-ll-status=\"loaded\"></span></span></p></td></tr></tbody></table></figure></div><p style=\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Du khách được tận hưởng cái thú trèo non hòa nhập với thiên nhiên hùng vĩ, cao rộng để đến với quần thể chùa chiền núi Hương Sơn như: Đền Trình, Chùa Thanh Sơn, chùa Long Vân, động Hinh Bồng, động Tuyết Sơn, đền Trấn Sơn, chùa Giải Oan, Thiên Trù… và cuối cùng là chùa Hương nằm trong động Hương Tích hay còn gọi là chùa Trong.&nbsp;Động Hương Tích nằm ở độ cao hơn 900 mét. Đường đi vào động tuy là đường núi quanh co, dốc cao nhưng việc đi lại cũng dễ dàng cho du khách thập phương hành hương thăm viếng. Hương Tích được mệnh danh “Nam Thiên đệ nhất động” – là nơi thờ Phật lớn nhất của di tích chùa Hương.</span></span></p><div class=\"table-responsive\" style=\"box-sizing:border-box;margin:0px;overflow-x:auto;padding:0px;\"><figure class=\"table\"><table style=\"border-collapse:collapse;box-sizing:border-box;height:256px;margin:0px;padding:0px;width:776.225px;\"><tbody style=\"box-sizing:border-box;margin:0px;padding:0px;\"><tr style=\"box-sizing:border-box;height:256px;margin:0px;padding:0px;\"><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;height:256px;margin:0px;padding:0.5em;text-align:center;width:383.925px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><img class=\"aligncenter wp-image-470 perfmatters-lazy entered pmloaded\" style=\"animation:500ms ease 0s 1 normal none running pmFadeIn;border-style:none;box-sizing:border-box;display:block;height:auto;margin:0px auto;max-width:100%;padding:0px;\" src=\"https://thesinhtour.com/wp-content/uploads/2015/01/chua-huong.jpg\" alt=\"tour chùa hương giá rẻ đầu năm\" decoding=\"async\" title=\"Tour chùa hương 1 ngày\" width=\"376\" height=\"282\" data-src=\"https://thesinhtour.com/wp-content/uploads/2015/01/chua-huong.jpg\" data-ll-status=\"loaded\"></span></span></p></td><td style=\"border-style:solid;border-width:1px;box-sizing:border-box;height:256px;margin:0px;padding:0.5em;width:391.5px;\"><p style=\"margin-left:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;\"><img class=\"alignnone wp-image-16214 aligncenter perfmatters-lazy entered pmloaded\" style=\"animation:500ms ease 0s 1 normal none running pmFadeIn;border-style:none;box-sizing:border-box;display:block;height:auto;margin:0px auto;max-width:100%;padding:0px;\" src=\"https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6.jpg\" alt=\"\" srcset=\"https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6.jpg 1080w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-300x225.jpg 300w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-1024x768.jpg 1024w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-768x576.jpg 768w\" sizes=\"(max-width: 384px) 100vw, 384px\" width=\"384\" decoding=\"async\" height=\"288\" data-src=\"https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6.jpg\" data-srcset=\"https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6.jpg 1080w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-300x225.jpg 300w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-1024x768.jpg 1024w, https://thesinhtour.com/wp-content/uploads/2015/01/Chua-Huong-6-768x576.jpg 768w\" data-sizes=\"(max-width: 384px) 100vw, 384px\" data-ll-status=\"loaded\"></span></span></p></td></tr></tbody></table><figcaption style=\"box-sizing:border-box;margin:0px;padding:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">Lên chùa Hương thắp nhang lấy lộc</span></i></em></span></figcaption></figure></div><p style=\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">&nbsp;Lễ hội chùa Hương tự ngàn đời đã đi vào thơ ca, nhạc họa của không biết bao nhiêu thế hệ thi nhân Việt Nam. Lễ hội chùa Hương cũng là một mốc thời gian để nói lời hẹn ước, đợi chờ của nối tiếp các thế hệ trai gái yêu nhau…Không phải ngẫu nhiên mà có câu :</span></span></p><p style=\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">“Gái chưa chồng vào hang Cắc Cơ</strong></span></i></em></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><span style=\"box-sizing:border-box;margin:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">Trai chưa vợ trẩy hội Chùa Hương”</strong></span></i></em></span></p><p style=\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">&nbsp;Đầu năm vãn cảnh <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">Tour&nbsp;chùa Hương 1 ngày giá rẻ</strong>, hành hương về nơi cõi Phật, được hòa mình vào non xanh nước biếc nơi này khiến lòng ta thanh thản hơn, tràn đầy sức sống hơn cho việc chinh phục những mục tiêu mới của tương lai phía trước….&nbsp;</span></span></p></div>', 3, '[{\"title\":\"S\\u00e1ng: Tour du l\\u1ecbch Ch\\u00f9a H\\u01b0\\u01a1ng 1 ng\\u00e0y \\u2013 Ch\\u00f9a Thi\\u00ean Tr\\u00f9\",\"content\":\"<p><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">7:30 \\u2013 8h10<\\/strong>: Xe v\\u00e0 h\\u01b0\\u1edbng d\\u1eabn vi\\u00ean s\\u1ebd \\u0111\\u00f3n qu\\u00fd kh\\u00e1ch t\\u1ea1i c\\u00e1c kh\\u00e1ch s\\u1ea1n trong khu v\\u1ef1c ph\\u1ed1 c\\u1ed5 H\\u00e0 N\\u1ed9i ho\\u1eb7c Nh\\u00e0 H\\u00e1t L\\u1edbn H\\u00e0 N\\u1ed9i.<\\/span><\\/span><br><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\">Kh\\u1edfi h\\u00e0nh \\u0111i Th\\u0103m quan l\\u1ec5 H\\u1ed9i Ch\\u00f9a H\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c kh\\u1edfi h\\u00e0nh h\\u00e0ng ng\\u00e0y ch\\u00f9a h\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c m\\u1ec7nh danh l\\u00e0 \\u201c<strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">Nam Thi\\u00ean \\u0110\\u1ec7 Nh\\u1ea5t \\u0110\\u1ed9ng<\\/strong>\\u201d.<\\/span><\\/span><br><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">10:00|<\\/strong>&nbsp;T\\u1edbi b\\u1ebfn \\u0110\\u1ee5c, qu\\u00fd kh\\u00e1ch l\\u00ean thuy\\u1ec1n \\u0111i v\\u00e0o b\\u1ebfn&nbsp;Thi\\u00ean Tr\\u00f9. T\\u1eeb b\\u1ebfn \\u0110\\u1ee5c v\\u00e0o b\\u1ebfn Thi\\u00ean Tr\\u00f9 kho\\u1ea3ng t\\u1ea7m 3km qu\\u00fd kh\\u00e1ch c\\u00f3 th\\u1ec3 ng\\u1eafm nh\\u00ecn d\\u00f2ng su\\u1ed1i Y\\u1ebfn th\\u01a1 m\\u1ed9ng v\\u1edbi nh\\u1eefng c\\u00e1nh \\u0111\\u1ed3ng l\\u00faa xanh &nbsp;m\\u00e1t, l\\u00e0n n\\u01b0\\u1edbc trong veo c\\u00f3 th\\u1ec3 nh\\u00ecn th\\u1ea5y \\u0111\\u00e1y c\\u1ee7a d\\u00f2ng su\\u1ed1i y\\u1ebfn n\\u00e0y.<\\/span><\\/span><br><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">11:00|<\\/strong>&nbsp;Qu\\u00fd kh\\u00e1ch V\\u00e0o t\\u1edbi&nbsp;b\\u1ebfn Thi\\u00ean Tr\\u00f9&nbsp;\\u0111i b\\u1ed9 15 ph\\u00fat s\\u1ebd l\\u00ean th\\u0103m quan&nbsp;ch\\u00f9a Thi\\u00ean Tr\\u00f9&nbsp;(c\\u00f3 ngh\\u0129a l\\u00e0 B\\u1ebfp Tr\\u1eddi). T\\u1ed5 ch\\u1ee9c c\\u00e1c ho\\u1ea1t \\u0111\\u1ed9ng ch\\u00ednh c\\u1ee7a Ch\\u00f9a H\\u01b0\\u01a1ng \\u0111\\u01b0\\u1ee3c di\\u1ec5n ra t\\u1ea1i \\u0111\\u00e2y,<\\/span><\\/span><br><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">12:00|<\\/strong>&nbsp;Qu\\u00fd kh\\u00e1ch v\\u1ec1 l\\u1ea1i nh\\u00e0 h\\u00e0ng ngh\\u1ec9 ng\\u01a1i v\\u00e0 d\\u00f9ng b\\u1eefa c\\u01a1m tr\\u01b0a tr\\u01b0\\u1edbc khi ti\\u1ebfp t\\u1ee5c h\\u00e0nh tr\\u00ecnh th\\u0103m quan&nbsp;\\u0110\\u1ed9ng H\\u01b0\\u01a1ng T\\u00edch ( Nam Thi\\u00ean \\u0110\\u1ec7 Nh\\u1ea5t \\u0110\\u1ed9ng)<\\/span><\\/span><\\/p>\"},{\"title\":\"Chi\\u1ec1u: Du L\\u1ecbch Ch\\u00f9a H\\u01b0\\u01a1ng 1 ng\\u00e0y \\u2013 \\u0110\\u1ed9ng H\\u01b0\\u01a1ng T\\u00edch\",\"content\":\"<p><span style=\\\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">13:00|<\\/strong>&nbsp;Qu\\u00fd Kh\\u00e1ch ti\\u1ebfp t\\u1ee5c h\\u00e0nh tr\\u00ecnh (&nbsp;\\u0110\\u1ed9ng H\\u01b0\\u01a1ng T\\u00edch&nbsp;)&nbsp;Khu du l\\u1ecbch Ch\\u00f9a H\\u01b0\\u01a1ng<strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">&nbsp;<\\/strong>l\\u00e0 m\\u1ed9t qu\\u1ea7n th\\u1ec3 t\\u00e2m linh, t\\u00f4n gi\\u00e1o \\u0111\\u1ea1o ph\\u1eadt. Trong \\u0111\\u00f3 l\\u1edbn nh\\u1ea5t ph\\u1ea3i k\\u1ec3 \\u0111\\u1ebfn l\\u00e0 \\u0111\\u1ed9ng H\\u01b0\\u01a1ng T\\u00edch, v\\u1edbi v\\u1ebb \\u0111\\u1eb9p v\\u00e0 v\\u1ecb tr\\u00ed m\\u00e0 thi\\u00ean nhi\\u00ean \\u0111\\u00e3 \\u01b0u \\u00e1i b\\u1ea1n t\\u1eb7ng cho n\\u01a1i \\u0111\\u00e2y. T\\u1ecda l\\u1ea1c tr\\u00ean \\u0111\\u1ec9nh m\\u1ed9i ng\\u1ecdn n\\u00fai cao nh\\u1ea5t trong d\\u00e3y H\\u01b0\\u01a1ng S\\u01a1n, \\u0111\\u00e3 t\\u1eebng \\u0111\\u01b0\\u1ee3c ch\\u00faa Tr\\u1ecbnh S\\u00e2m m\\u1ec7nh danh l\\u00e0 <\\/span><em style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><i><span style=\\\"-webkit-text-stroke-width:0px;box-sizing:border-box;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\">\\u201cNam thi\\u00ean \\u0111\\u1ec7 nh\\u1ea5t