2013 13h00:<\\/strong>\\u0102n tr\\u01b0a t\\u1ea1i nh\\u00e0 h\\u00e0ng d\\u01b0\\u1edbi ch\\u00e2n n\\u00fai v\\u1edbi c\\u00e1c m\\u00f3n \\u0103n \\u0111\\u1eadm ch\\u1ea5t n\\u00fai r\\u1eebng Y\\u00ean T\\u1eed.<\\/span><\\/span><\\/p><p style=\\\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">13h00 \\u2013 14h00: <\\/strong>T\\u1ef1 do mua s\\u1eafm v\\u00e0 tham quan tr\\u1ea3i nghi\\u1ec7m t\\u1ea1i L\\u00e0ng N\\u01b0\\u01a1ng&nbsp;<\\/span><\\/span><\\/p><p style=\\\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">14h00: <\\/strong>Xe \\u0111\\u00f3n qu\\u00fd kh\\u00e1ch l\\u00ean xe v\\u1ec1 H\\u00e0 N\\u1ed9i. Tr\\u00ean \\u0111\\u01b0\\u1eddng v\\u1ec1, qu\\u00fd kh\\u00e1ch d\\u1eebng ch\\u00e2n ngh\\u1ec9 ng\\u01a1i mua s\\u1eafm \\u0111\\u1eb7c s\\u1ea3n t\\u1ea1i H\\u1ea3i D\\u01b0\\u01a1ng.<\\/span><\\/span><\\/p><p style=\\\"box-sizing:border-box;margin:0px 0px 15px;padding:0px;text-align:justify;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">17h00:<\\/strong>&nbsp;Xe \\u0111\\u01b0a qu\\u00fd kh\\u00e1ch v\\u1ec1 \\u0111\\u1ebfn H\\u00e0 N\\u1ed9i, k\\u1ebft th\\u00fac ch\\u01b0\\u01a1ng tr\\u00ecnh&nbsp;<\\/span><\\/span><a style=\\\"box-sizing:border-box;color:rgb(16, 90, 142);margin:0px;padding:0px;text-decoration:none;\\\" href=\\\"https:\\/\\/thesinhtour.com\\/tour-du-lich-yen-tu-1-ngay\\/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">Tour&nbsp;du l\\u1ecbch Y\\u00ean T\\u1eed 1 ng\\u00e0y<\\/strong><\\/span><\\/span><\\/a><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">&nbsp;c\\u1ee7a The Sinh Tourist<\\/strong>. Chia tay v\\u00e0 ch\\u00e0o t\\u1ea1m bi\\u1ec7t Qu\\u00fd kh\\u00e1ch.<\\/span><\\/span><\\/p><\\/div><\\/div>\"}]', '/userfiles/images/tours/hanoi/chua%20dong.jpg', NULL, 'tour-du-lich-yen-tu-1-ngay', '<p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">►ĐIỀU KHOẢN ÁP DỤNG</strong></span></span></p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Phải gửi đầy đủ thông tin chính xác và đầy đủ về Họ tên + số điện thoại liên hệ</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Quý khách là người ăn chay vui lòng báo trước tối thiểu 24 giờ để công ty sắp xếp dễ dàng.</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Bất cứ dịch vụ nào trong tour nếu Quý khách không sử dụng cũng không được hoàn lại</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">– Hướng dẫn viên có quyền sắp xếp lại thứ tự các điểm thăm quan cho phù hợp điều kiện từng ngày khởi</span></span><br><span style=\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\"><span style=\"box-sizing:border-box;margin:0px;padding:0px;\">hành cụ thể nhưng vẫn đảm bảo tất cả các điểm thăm quan trong chương trình.</span></span></p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">Hãy dành một ngày để rời xa cuộc sống bộn bề, về với chốn thiêng Yên Tử, nơi tâm hồn được thanh lọc và an yên.</strong></p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">📌 <strong style=\"box-sizing:border-box;margin:0px;padding:0px;\">Đặt tour ngay hôm nay</strong> để tận hưởng hành trình trọn vẹn, dịch vụ chu đáo và trải nghiệm ý nghĩa nhất!</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><em style=\"box-sizing:border-box;margin:0px;padding:0px;\"><i><strong style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:arial, helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Chúc quý khách có chuyến đi Tour du lịch Yên Tử 1 ngày thoải mái về tinh thần và tâm linh tín ngưỡng, đạt được nhiều niềm vui trong cuộc sống!.</strong></i></em></p>', NULL, NULL, '2025-09-09 02:05:59', '2025-09-09 02:05:59'),
(6, 'TRANGAN001', 'Tour Tràng An – Bái Đính 1 ngày', '1 ngày', 'Hà Nội', 100, 750000, 750000, 750000, 750000, 'Ô tô', 'Đến với Tour Bái Đính – Tràng An 1 ngày, du khách sẽ được đến thăm quan những danh thắng đẹp nổi tiếng ở Ninh Bình như Khu núi chùa Bái Đính nổi tiếng bởi 5 cái nhất: chuông to nhất, nhiều tượng La Hán nhất, chùa lớn nhất, tượng Phật to nhất, khuôn viên rộng nhất. Tràng An là một khu du lịch sinh thái nằm trong Quần thể di sản thế giới Tràng An thuộc tỉnh Ninh Bình.\r\nNơi đây đã được Chính phủ Việt Nam xếp hạng di tích quốc gia đặc biệt quan trọng và UNESCO công nhận là di sản thế giới kép từ năm 2014. Tràng An vốn được gọi là thành Nam của kinh đô Hoa Lư xưa, nay là cố đô Hoa Lư. Hành trình đưa bạn khám phá chùa Bái Đính – ngôi chùa lớn nhất Đông Nam Á và khu du lịch sinh thái Tràng An, nơi được UNESCO công nhận là di sản thiên nhiên và văn hóa thế giới.', NULL, 5, '[{\"title\":\"S\\u00e1ng: Ch\\u00f9a B\\u00e1i \\u0110\\u00ednh\",\"content\":\"<p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">07h15 \\u2013 8:00|<\\/strong>&nbsp;Xe v\\u00e0 H\\u01b0\\u1edbng d\\u1eabn vi\\u00ean s\\u1ebd \\u0111\\u00f3n qu\\u00fd kh\\u00e1ch t\\u1ea1i \\u0111i\\u1ec3m h\\u1eb9n kh\\u1edfi h\\u00e0nh \\u0111i <strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">Tour B\\u00e1i \\u0110\\u00ednh \\u2013 Tr\\u00e0ng An&nbsp; 1 ng\\u00e0y<\\/strong> c\\u00e1ch H\\u00e0 N\\u1ed9i kho\\u1ea3ng 100km. Xe s\\u1ebd d\\u1eebng ngh\\u1ec9 ng\\u01a1i 15 ph\\u00fat t\\u1ea1i Ph\\u1ee7 L\\u00fd \\u0111\\u1ec3 kh\\u00e1ch h\\u00e0ng t\\u1ef1 t\\u00fac \\u0103n s\\u00e1ng.<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 15px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">10h30|<\\/strong>&nbsp;\\u0110\\u1ebfn ch\\u00f9a B\\u00e1i \\u0110\\u00ednh, t\\u1eeb b\\u00e3i \\u0111\\u1ed7 xe qu\\u00fd kh\\u00e1ch l\\u00ean xe \\u0111i\\u1ec7n di chuy\\u1ec3n \\u0111\\u1ebfn c\\u1ed5ng ch\\u00f9a B\\u00e1i \\u0110\\u00ednh ( kho\\u1ea3ng 3km ). Qu\\u00fd kh\\u00e1ch th\\u0103m&nbsp;<\\/span><em style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><i><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">ch\\u00f9a B\\u00e1i \\u0110\\u00ednh<\\/strong><\\/span><\\/i><\\/em><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">&nbsp;n\\u1ed5i ti\\u1ebfng v\\u1edbi nhi\\u1ec1u k\\u1ef7 l\\u1ee5c: Khu\\u00f4n vi\\u00ean c\\u1ea3 khu ch\\u00f9a B\\u00e1i \\u0110\\u00ednh c\\u00f3 di\\u1ec7n t\\u00edch 107ha, trong \\u0111\\u00f3, \\u0110i\\u1ec7n th\\u1edd Tam Th\\u1ebf v\\u00e0 Ph\\u00e1p Ch\\u1ee7 r\\u1ed9ng h\\u00e0ng ng\\u00e0n m\\u00e9t vu\\u00f4ng; t\\u1ea1i ng\\u00f4i ch\\u00f9a n\\u00e0y c\\u00f3 t\\u01b0\\u1ee3ng<strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">&nbsp;<\\/strong>Ph\\u1eadt T\\u1ed5 Nh\\u01b0 Lai&nbsp;b\\u1eb1ng \\u0111\\u1ed3ng l\\u1edbn nh\\u1ea5t \\u0110\\u00f4ng Nam \\u00c1 n\\u1eb7ng 100 t\\u1ea5n v\\u00e0 ba pho t\\u01b0\\u1ee3ng Tam Th\\u1ebf, m\\u1ed7i pho n\\u1eb7ng 50 t\\u1ea5n. c\\u00e1c hang \\u0111\\u1ed9ng \\u1edf \\u0111\\u00e2y c\\u0169ng c\\u00f3 nhi\\u1ec1u nh\\u0169 \\u0111\\u00e1 \\u0111\\u1eb9p kh\\u00f4ng k\\u00e9m nh\\u1eefng hang \\u0111\\u1ed9ng \\u1edf v\\u1ecbnh H\\u1ea1 Long.&nbsp;Ch\\u00f9a B\\u00e1i \\u0110\\u00ednh&nbsp;\\u0111\\u00e3 tr\\u1edf th\\u00e0nh \\u0111i\\u1ec3m h\\u00e0nh h\\u01b0\\u01a1ng v\\u00e0&nbsp;<\\/span><\\/span><a style=\\\"box-sizing:border-box;color:rgb(0, 0, 0);margin:0px;padding:0px;text-decoration:none;\\\" href=\\\"https:\\/\\/thesinhtour.com\\/du-lich-mien-bac\\/\\\" title=\\\"du l\\u1ecbch mi\\u1ec1n b\\u1eafc\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">du l\\u1ecbch Mi\\u1ec1n B\\u1eafc<\\/strong><\\/span><\\/span><\\/a><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">&nbsp;thu h\\u00fat \\u0111\\u00f4ng \\u0111\\u1ea3o du kh\\u00e1ch trong v\\u00e0 ngo\\u00e0i n\\u01b0\\u1edbc.<\\/span><\\/span><br>&nbsp;<\\/p><p><img class=\\\"wp-caption alignnone\\\" style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(221, 221, 221);box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-varian