ation-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">12h00<\\/strong>: Qu\\u00fd kh\\u00e1ch \\u0103n tr\\u01b0a t\\u1ea1i nh\\u00e0 h\\u00e0ng \\u0111\\u1ecba ph\\u01b0\\u01a1ng v\\u1edbi nhi\\u1ec1u \\u0111\\u1eb7c s\\u1ea3n nh\\u01b0 th\\u1ecbt d\\u00ea, c\\u01a1m ch\\u00e1y\\u2026<\\/span><\\/span><\\/p><p style=\\\"-webkit-text-stroke-width:0px;background-color:white;box-sizing:border-box;color:rgb(0, 0, 0);font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;line-height:24px;margin:0cm 0cm 0.0001pt;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\\\"><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\"><strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">13h00<\\/strong>: H\\u01b0\\u1edbng d\\u1eabn vi\\u00ean s\\u1ebd \\u0111\\u01b0a qu\\u00fd kh\\u00e1ch ra <strong style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">b\\u1ebfn \\u0111\\u00f2 Tam C\\u1ed1c.<\\/strong><\\/span><\\/span><br><span style=\\\"color:rgb(0,0,0);font-family:arial, helvetica, sans-serif;font-size:12pt;\\\"><span style=\\\"box-sizing:border-box;margin:0px;padding:0px;\\\">Qu\\u00fd kh\\u00e1ch l\\u00ean thuy\\u1ec1n \\u0111i th\\u0103m c\\u00e1c hang \\u0111\\u1ed9ng. \\u0110i qua 3 hang: hang C\\u1ea3, hang Hai, hang Ba. Tam C\\u00f4\\u0301c n\\u01a1i co\\u0301 ve\\u0309 \\u0111e\\u0323p \\u0111\\u00f4\\u0323c nh\\u00e2\\u0301t v\\u00f4 nhi\\u0323, n\\u01a1i \\u0111\\u01b0\\u01a1\\u0323c so sa\\u0301nh v\\u01a1\\u0301i ve\\u0309 \\u0111e\\u0323p cu\\u0309a Vi\\u0323nh Ha\\u0323 Long, v\\u01a1\\u0301i 1 ti\\u00ea\\u0301ng r\\u01b0\\u01a1\\u0303i che\\u0300o \\u0111o\\u0300 cu\\u0300ng ng\\u01b0\\u01a1\\u0300i \\u0111i\\u0323a ph\\u01b0\\u01a1ng, quy\\u0301 kha\\u0301ch se\\u0303 co\\u0301 c\\u01a1 h\\u00f4\\u0323i t\\u00e2\\u0323n h\\u01b0\\u01a1\\u0309ng \\u0111\\u01b0\\u01a1\\u0323c ve\\u0309 \\u0111e\\u0323p tuy\\u00ea\\u0323t v\\u01a1\\u0300i n\\u01a1i \\u0111\\u00e2y mang la\\u0323i.<\\/span><\\/span><br>&nbsp;<\\/p><p><img class=\\\"image_resized wp-caption aligncenter\\\" style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(221, 221, 221);box-sizing:border-box;color:rgb(0, 0, 0);display:block;font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:10px auto;max-width:100%;orphans:2;padding:5px;text-align:center;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;width:1872px;word-spacing:0px;\\\" src=\\\"https:\\/\\/thesinhtour.com\\/wp-content\\/uploads\\/2020\\/09\\/Ninh-binh-day-tour-12.jpg\\\" alt=\\\"Tam C\\u1ed1c Ninh B\\u00ecnh\\\" id=\\\"attachment_21490\\\"><\\/p><div class=\\\"wp-caption aligncenter\\\" style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(221, 221, 221);box-sizing:border-box;color:rgb(0, 0, 0);display:block;font-family:Roboto, Arial, Helvetica, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:10px auto;max-width:100%;orphans:2;padding:5px;text-align:center;text-decoration-color:initial;text-decoration-style:initial;text-decorat