INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(18, 'QUANGBINH001', 'Tour du lịch Phong Nha Kẻ Bàng 3 ngày từ Hà Nội', '3 ngày 3 đêm', 'Hà Nội', 100, 3136000, 3136000, 3136000, 3136000, 'Ô tô', 'Phong Nha Kẻ Bàng là một vùng khí hậu trong lành, mát lạnh quanh năm trung bình chỉ 20 - 24 độ C được đánh giá là một trong hai vùng núi đá vôi rộng nhất thế giới, với diện tích trên 200.000 ha (trong đó, diện tích vùng lõi là 85.754 ha và một vùng đệm rộng 195.400 ha).\r\nĐặc trưng của khu vườn quốc gia này là những kiến tạo đá vôi dạng karst hàng triệu năm tuổi với hơn 300 hang động và hệ thống các sông ngầm. Hàng trăm loài động, thực vật quý hiếm đang tồn tại, trong đó có nhiều loài có tên trong sách đỏ Việt Nam và thế giới, chính là nguồn cảm hứng cho du khách và các nhà khoa học về đây khám phá.\r\nTour du lịch Phong Nha Kẻ Bàng - Biển Nhật Lệ là một điển đến hấp dẫn không thể bỏ qua với mỗi du khách trong bất kỳ thời điểm nào trong năm. Đến Đồng Hới du khách không khỏi ngỡ ngàng bởi vẻ đẹp của những bãi cát trắng xóa, làn nước trong xanh, hang động kì vỹ có một không hai này.', NULL, 5, '[{\"title\":\"\\u0110\\u00eam 01: H\\u00e0 N\\u1ed9i - \\u0110\\u1ed3ng H\\u1edbi\",\"content\":\"<p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(34, 34, 34);font-family:Roboto, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;line-height:1.5em;list-style:initial;margin:0px 20px;orphans:2;padding:0px 0px 0px 10px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;transition:0.5s;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;font-family:Roboto, sans-serif !important;line-height:1.5em;transition:0.5s;\\\">19h00<\\/strong>: H\\u01b0\\u1edbng d\\u1eabn vi\\u00ean c\\u1ee7a<strong style=\\\"box-sizing:border-box;font-family:Roboto, sans-serif !important;line-height:1.5em;transition:0.5s;\\\"> S\\u00f4ng H\\u1ed3ng Tourist<\\/strong> \\u0111\\u00f3n qu\\u00fd kh\\u00e1ch t\\u1ea1i \\u0111i\\u1ec3m h\\u1eb9n kh\\u1edfi h\\u00e0nh l\\u00fac 19h30 \\u0111i <strong style=\\\"box-sizing:border-box;font-family:Roboto, sans-serif !important;line-height:1.5em;transition:0.5s;\\\">\\u0110\\u1ed3ng H\\u1edbi<\\/strong>. Ngh\\u1ec9 \\u0111\\u00eam tr\\u00ean xe.<\\/p>\"},{\"title\":\"Ng\\u00e0y 01: \\u0110\\u1ed3ng H\\u1edbi - Bi\\u1ec3n Nh\\u1eadt L\\u1ec7 (\\u0102n: S\\u00e1ng, tr\\u01b0a, t\\u1ed1i)\",\"content\":\"<p style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);border-style:none;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:Roboto, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;line-height:1.5em;margin:0px;orphans:2;padding:0px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;transition:0.5s;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;font-family:Roboto, sans-serif !important;line-height:1.5em;transition:0.5s;\\\">Bu\\u1ed5i s\\u00e1ng<\\/strong>:<\\/p><ul><li style=\\\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(34, 34, 34);font-family:Roboto, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;line-height:1.5em;list-style:initial;margin:0px 20px;orphans:2;padding:0px 0px 0px 10px;text-align:justify;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;transition:0.5s;white-space:normal;widows:2;word-spacing:0px;\\\"><strong style=\\\"box-sizing:border-box;font-family:Roboto, sans-serif !important;line-height:1.5em;tr