INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(20, 'DANANG001', 'TOUR ĐÀ NẴNG – CÙ LAO CHÀM – HỘI AN – BÀ NÀ', '3 ngày 2 đêm', 'TPHCM', 100, 3490000, 3490000, 3490000, 3490000, 'Máy Bay, Ô tô', NULL, NULL, 10, '[{\"title\":\"Ng\\u00e0y 1: TP. HCM \\u2013 \\u0110\\u00c0 N\\u1eb4NG \\u2013 S\\u01a0N TR\\u00c0\",\"content\":\"<p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0110\\u00f3n qu\\u00fd kh\\u00e1ch t\\u1ea1i <span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">s\\u00e2n bay T\\u00e2n S\\u01a1n Nh\\u1ea5t<\\/strong><\\/span><\\/span>, \\u0111\\u00e1p chuy\\u1ebfn bay kh\\u1edfi h\\u00e0nh \\u0111i \\u0110\\u00e0 N\\u1eb5ng <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>(c\\u00e1c chuy\\u1ebfn bay d\\u1ef1 ki\\u1ebfn t\\u1eeb 07:00 \\u2013 09:30). <\\/i><\\/em>\\u0110\\u1ebfn \\u0110\\u00e0 N\\u1eb5ng, xe v\\u00e0 HDV \\u0111\\u00f3n kh\\u00e1ch.<\\/p><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n tr\\u01b0a \\u0111\\u1eb7c s\\u1ea3n \\u0110\\u00e0 N\\u1eb5ng <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>\\u201cB\\u00e1nh tr\\u00e1ng th\\u1ecbt heo 2 \\u0111\\u1ea7u da &amp; m\\u00ec Qu\\u1ea3ng\\u201d<\\/i><\\/em>. Nh\\u1eadn ph\\u00f2ng, ngh\\u1ec9 ng\\u01a1i.<\\/p><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">Bu\\u1ed5i chi\\u1ec1u, kh\\u1edfi h\\u00e0nh tham quan <span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">b\\u00e1n \\u0111\\u1ea3o S\\u01a1n Tr\\u00e0<\\/strong><\\/span><\\/span> ng\\u1eafm ph\\u1ed1 bi\\u1ec3n t\\u1eeb tr\\u00ean cao.<\\/p><ul><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">Vi\\u1ebfng<span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"> Linh \\u1ee8ng T\\u1ef1<\\/strong><\\/span><\\/span> \\u2013 n\\u01a1i c\\u00f3 t\\u01b0\\u1ee3ng Ph\\u1eadt B\\u00e0 cao 67 m\\u00e9t cao nh\\u1ea5t Vi\\u1ec7t Nam.<\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">C\\u00f4ng vi\\u00ean k\\u1ef3 quan th\\u1ebf gi\\u1edbi \\u0110\\u00e0 N\\u1eb5ng<\\/strong><\\/span><\\/span> \\u2013 c\\u00f4ng tr\\u00ecnh thu nh\\u1ecf m\\u00f4 ph\\u1ecfng 9 k\\u1ef3 quan th\\u1ebf gi\\u1edbi v\\u00e0 c\\u00e1c \\u0111\\u1ecba danh n\\u1ed5i ti\\u1ebfng t\\u1ea1i Vi\\u1ec7t Nam.<\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">T\\u1eafm bi\\u1ec3n<span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"> M\\u1ef9 Kh\\u00ea<\\/strong> <\\/span><\\/span>\\u2013 t\\u1eebng \\u0111\\u01b0\\u1ee3c t\\u1ea1p ch\\u00ed Forbes b\\u00ecnh ch\\u1ecdn l\\u00e0&nbsp;b\\u00e3i bi\\u1ec3n quy\\u1ebfn r\\u0169 nh\\u1ea5t h\\u00e0nh tinh.<\\/li><\\/ul><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n t\\u1ed1i. T\\u1ef1 do th\\u01b0\\u1edfng ngo\\u1ea1n du thuy\\u1ec1n s\\u00f4ng H\\u00e0n ng\\u1eafm c\\u1ea3nh \\u0110\\u00e0 Th\\u00e0nh v\\u1ec1 \\u0111\\u00eam. <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>(chi ph\\u00ed t\\u1ef1 t\\u00fac)<\\/i><\\/em><\\/p>\"},{\"title\":\"Ng\\u00e0y 2: \\u0110\\u00c0 N\\u1eb4NG \\u2013 C\\u00d9 LAO CH\\u00c0M \\u2013 H\\u1ed8I AN\",\"content\":\"<p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n s\\u00e1ng buffet t\\u1ea1i kh\\u00e1ch s\\u1ea1n. Di chuy\\u1ec3n v\\u00e0o H\\u1ed9i An, \\u0111\\u1ebfn bi\\u1ec3n C\\u1eeda \\u0110\\u1ea1i, ng\\u1ed3i t\\u00e0u cao t\\u1ed1c kh\\u1edfi h\\u00e0nh \\u0111i <span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">C\\u00f9 Lao Ch\\u00e0m<\\/strong><\\/span><\\/span> \\u2013 khu d\\u1ef1 tr\\u1eef sinh quy\\u1ec3n th\\u1ebf gi\\u1edbi.<\\/p><ul><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">Tr\\u1ea3i nghi\\u1ec7m cano cao t\\u1ed1c<\\/strong><\\/span><\\/span> l\\u01b0\\u1edbt tr\\u00ean bi\\u1ec3n xanh, cano c\\u1eadp c\\u1ea3ng B\\u00e3i L\\u00e0ng C\\u00f9 Lao.<\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">Khu tr\\u01b0ng b\\u00e0y n\\u1ec1n v\\u0103n h\\u00f3a Sa Hu\\u1ef3nh, khu b\\u1ea3o t\\u1ed3n bi\\u1ec3n C\\u00f9 Lao Ch\\u00e0m, ch\\u00f9a H\\u1ea3i T\\u1ea1ng c\\u1ed5, ch\\u1ee3 h\\u1ea3i s\\u1ea3n T\\u00e2n Hi\\u1ec7p<\\/strong>\\u2026<\\/span><\\/span><\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">Tham gia c\\u00e1c ho\\u1ea1t \\u0111\\u1ed9ng l\\u1eb7n bi\\u1ec3n <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>(Snorkeling) <\\/i><\\/em>ng\\u1eafm san h\\u00f4.<\\/li><\\/ul><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n tr\\u01b0a t\\u1ea1i C\\u00f9 Lao Ch\\u00e0m. Cano \\u0111\\u01b0a kh\\u00e1ch tr\\u1edf v\\u1ec1 \\u0111\\u1ea5t li\\u1ec1n. Tham quan:<\\/p><ul><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">Ph\\u1ed1 c\\u1ed5 H\\u1ed9i An<\\/strong><\\/span><\\/span> \\u2013 du kh\\u00e1ch t\\u1ea3n b\\u1ed9 kh\\u00e1m ph\\u00e1 c\\u00e1c c\\u00f4ng tr\\u00ecnh ki\\u1ebfn tr\\u00fac n\\u1ed5i ti\\u1ebfng: <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>Ch\\u00f9a C\\u1ea7u Nh\\u1eadt B\\u1ea3n, c\\u00e1c ng\\u00f4i nh\\u00e0 c\\u1ed5 h\\u00e0ng tr\\u0103m tu\\u1ed5i, H\\u1ed9i Qu\\u00e1n Ph\\u01b0\\u1edbc Ki\\u1ebfn, X\\u01b0\\u1edfng th\\u1ee7 c\\u00f4ng m\\u1ef9 ngh\\u1ec7<\\/i><\\/em>. Ph\\u1ed1 c\\u1ed5 H\\u1ed9i An l\\u00e0 qu\\u00e1 kh\\u1ee9 v\\u00e0ng son c\\u1ee7a m\\u1ed9t th\\u01b0\\u01a1ng c\\u1ea3ng s\\u1ea7m u\\u1ea5t th\\u1eddi phong ki\\u1ebfn.<\\/li><\\/ul><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n t\\u1ed1i. Kh\\u1edfi h\\u00e0nh v\\u1ec1 l\\u1ea1i \\u0110\\u00e0 N\\u1eb5ng. T\\u1ef1 do kh\\u00e1m ph\\u00e1 \\u0110\\u00e0 N\\u1eb5ng v\\u1ec1 \\u0111\\u00eam. Ngh\\u1ec9 \\u0111\\u00eam t\\u1ea1i <span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">\\u0110\\u00e0 N\\u1eb5ng<\\/strong><\\/span><\\/span>.<\\/p>\"},{\"title\":\"Ng\\u00e0y 3: \\u0110\\u00c0 N\\u1eb4NG \\u2013 B\\u00c0 N\\u00c0 \\u2013 TP. HCM\",\"content\":\"<p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">\\u0102n s\\u00e1ng buffet t\\u1ea1i kh\\u00e1ch s\\u1ea1n. Tr\\u1ea3 ph\\u00f2ng. Kh\\u1edfi h\\u00e0nh tham quan:<\\/p><ul><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">Khu du l\\u1ecbch B\\u00e0 N\\u00e0 Hills<\\/strong><\\/span><\\/span> \\u2013 chinh ph\\u1ee5c B\\u00e0 N\\u00e0 b\\u1eb1ng h\\u1ec7 th\\u1ed1ng c\\u00e1p treo m\\u1ed9t d\\u00e2y d\\u00e0i nh\\u1ea5t th\\u1ebf gi\\u1edbi 5.801m v\\u00e0 l\\u00e0 m\\u1ed9t trong 10 tuy\\u1ebfn c\\u00e1p treo \\u1ea5n t\\u01b0\\u1ee3ng nh\\u1ea5t th\\u1ebf gi\\u1edbi. B\\u00e0 N\\u00e0 l\\u00e0 n\\u01a1i c\\u00f3 nh\\u1eefng kho\\u1ea3nh kho\\u1eafc giao m\\u00f9a b\\u1ea5t ng\\u1edd <em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i>Xu\\u00e2n \\u2013 H\\u1ea1 \\u2013 Thu \\u2013 \\u0110\\u00f4ng<\\/i><\\/em> trong m\\u1ed9t ng\\u00e0y.<\\/li><\\/ul><p style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(255,0,0);font-size:16px;\\\"><em style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><i><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">(chi ph\\u00ed c\\u00e1p treo B\\u00e0 N\\u00e0 t\\u1ef1 t\\u00fac)<\\/strong><\\/span><\\/i><\\/em><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">.<\\/span><\\/span><\\/p><ul><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">Ch\\u00f9a Linh \\u1ee8ng<\\/strong><\\/span><\\/span> v\\u1edbi t\\u01b0\\u1ee3ng Ph\\u1eadt Th\\u00edch Ca cao 27m, \\u0111\\u1ec1n th\\u1edd <span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">B\\u00e0 Ch\\u00faa M\\u1eabu Th\\u01b0\\u1ee3ng Ng\\u00e0n<\\/strong><\\/span><\\/span>.<\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\"><span style=\\\"background-color:transparent;color:rgb(0,0,128);font-size:16px;\\\"><span style=\\\"-webkit-font-smoothing:antialiased;border-width:0px;box-sizing:border-box;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\"><strong style=\\\"-webkit-font-smoothing:antialiased;background-color:transparent;border-width:0px;box-sizing:border-box;font-size:16px;margin:0px;outline:0px;padding:0px;vertical-align:baseline;\\\">C\\u1ea7u V\\u00e0ng<\\/strong><\\/span><\\/span> \\u2013 c\\u00e2y c\\u1ea7u \\u0111\\u1ed9c \\u0111\\u00e1o n\\u1eb1m trong v\\u01b0\\u1eddn Thi\\u00ean Thai, \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng tr\\u00ean \\u0111\\u1ed9 cao 1.400m so v\\u1edbi m\\u1eb7t n\\u01b0\\u1edbc bi\\u1ec3n, \\u0111\\u01b0\\u1ee3c n\\u00e2ng \\u0111\\u1ee1 b\\u1edfi ki\\u1ebfn tr\\u00fac h\\u00ecnh \\u0111\\u00f4i b\\u00e0n tay kh\\u1ed5ng l\\u1ed3 \\u0111\\u1ed9c \\u0111\\u00e1o.<\\/li><li style=\\\"-webkit-font-smoothing:antialiased;-webkit-text-stroke-width:0px;background-color:transparent;border-width:0px;box-sizing:border-box;color:rgb(34, 34, 34);font-family:;\\\" bai=\\\"\\\">Vui ch\\