INSERT INTO `tours` (`id`, `tour_code`, `name`, `duration`, `departure_point`, `remaining_slots`, `price_adult`, `price_child`, `price_toddler`, `price_infant`, `transport_mode`, `short_description`, `tour_description`, `priority`, `tour_schedule`, `thumbnail`, `images`, `slug`, `services_note`, `note`, `characteristic`, `created_at`, `updated_at`) VALUES
(24, 'CANTHO001', 'Tour Mỹ Tho – Cồn Thới Sơn – Bến Tre – Cần Thơ – Chợ Nổi Cái Răng – Mỹ Khánh', '2 ngày 1 đêm', 'TPHCM', 100, 1990000, 1990000, 1990000, 1990000, 'Ô tô', 'Khám phá miền Tây sông nước với hành trình đặc sắc qua Mỹ Tho, du ngoạn sông Tiền và tham quan Cồn Thới Sơn. Trải nghiệm Bến Tre với làng nghề truyền thống, xuồng chèo len lỏi giữa rặng dừa xanh.\r\nĐến Cần Thơ, ghé thăm Chợ Nổi Cái Răng nhộn nhịp – nét văn hóa độc đáo chỉ có ở miền Tây. Kết thúc tại Làng Du Lịch Mỹ Khánh với không gian miệt vườn, ẩm thực dân gian và nhiều trải nghiệm thú vị.', NULL, 15, '[{\"title\":\"Ng\\u00e0y 1: TP.H\\u1ed3 Ch\\u00ed Minh \\u2013 M\\u1ef9 Tho \\u2013 C\\u1ed3n Th\\u1edbi S\\u01a1n \\u2013 B\\u1ebfn Tre \\u2013 C\\u1ea7n Th\\u01a1\",\"content\":\"<p>\\u0110\\u00f3n Qu\\u00fd kh\\u00e1ch t\\u1ea1i Vietravel 190 Pasteur, qu\\u1eadn 3, th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh, kh\\u1edfi h\\u00e0nh \\u0111i mi\\u1ec1n M\\u1ef9 Tho theo tuy\\u1ebfn cao t\\u1ed1c th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh - Trung L\\u01b0\\u01a1ng ng\\u1eafm nh\\u00ecn nh\\u1eefng c\\u00e1nh \\u0111\\u1ed3ng l\\u00faa v\\u00e0 m\\u00e0u xanh v\\u01b0\\u1eddn t\\u01b0\\u1ee3c hai b\\u00ean \\u0111\\u01b0\\u1eddng. \\u0110o\\u00e0n d\\u1eebng ch\\u00e2n \\u0103n s\\u00e1ng d\\u1ecdc \\u0111\\u01b0\\u1eddng.&nbsp;<\\/p><p>\\u0110\\u1ebfn b\\u1ebfn t\\u00e0u du l\\u1ecbch M\\u1ef9 Tho, Qu\\u00fd kh\\u00e1ch b\\u1eaft \\u0111\\u1ea7u h\\u00e0nh tr\\u00ecnh du ngo\\u1ea1n tr\\u00ean s\\u00f4ng Mekong: Chi\\u00eam ng\\u01b0\\u1ee1ng C\\u1ea7u R\\u1ea1ch Mi\\u1ec5u: c\\u1ea7u d\\u00e2y v\\u0103ng \\u0111\\u1ea7u ti\\u00ean do k\\u1ef9 s\\u01b0 Vi\\u1ec7t Nam thi\\u1ebft k\\u1ebf v\\u00e0 x\\u00e2y d\\u1ef1ng, nghe gi\\u1edbi thi\\u1ec7u c\\u00e1c c\\u00f9 lao Long - L\\u00e2n - Quy - Ph\\u1ee5ng. Ng\\u1eafm nh\\u00ecn c\\u1ea3ng c\\u00e1 M\\u1ef9 Tho, l\\u00e0ng nu\\u00f4i c\\u00e1 b\\u00e8 d\\u1ecdc s\\u00f4ng Ti\\u1ec1n, th\\u01b0\\u1edfng th\\u1ee9c n\\u01b0\\u1edbc d\\u1eeba t\\u01b0\\u01a1i tr\\u00ean t\\u00e0u. \\u0110\\u1ebfn c\\u00f9 lao Th\\u1edbi S\\u01a1n, t\\u1ea3n b\\u1ed9 tr\\u00ean \\u0111\\u01b0\\u1eddng l\\u00e0ng, tham quan v\\u01b0\\u1eddn c\\u00e2y \\u0103n tr\\u00e1i. \\u0110i xu\\u1ed3ng ch\\u00e8o len l\\u1ecfi trong r\\u1ea1ch nh\\u1ecf ng\\u1eafm nh\\u00ecn phong c\\u1ea3nh b\\u00ecnh d\\u1ecb v\\u00f9ng s\\u00f4ng n\\u01b0\\u1edbc, \\u0111\\u1ebfn tham quan tr\\u1ea1i nu\\u00f4i ong m\\u1eadt, th\\u01b0\\u1edfng th\\u1ee9c tr\\u00e0 m\\u1eadt ong, r\\u01b0\\u1ee3u chu\\u1ed1i h\\u1ed9t\\u2026&nbsp;<\\/p><p>Ti\\u1ebfp t\\u1ee5c, xu\\u00f4i d\\u00f2ng s\\u00f4ng Ti\\u1ec1n \\u0111\\u1ebfn T\\u00e2n Th\\u1ea1ch (B\\u1ebfn Tre) tham quan l\\u00f2 k\\u1eb9o d\\u1eeba \\u0111\\u1eb7c s\\u1ea3n B\\u1ebfn Tre, l\\u00e0ng ngh\\u1ec1 th\\u1ee7 c\\u00f4ng m\\u1ef9 ngh\\u1ec7 truy\\u1ec1n th\\u1ed1ng. D\\u00f9ng \\u0111\\u00f2 m\\u00e1y kh\\u00e1m ph\\u00e1 con R\\u1ea1ch (T\\u00e2n Th\\u1ea1ch) t\\u00ecm hi\\u1ec3u cu\\u1ed9c s\\u1ed1ng th\\u01b0\\u1eddng nh\\u1eadt c\\u1ee7a ng\\u01b0\\u1eddi d\\u00e2n mi\\u1ec1n qu\\u00ea. Tr\\u1ea3i nghi\\u1ec7m l\\u00e0m b\\u00e1nh kh\\u1ecdt nh\\u00e2n t\\u00f4m n\\u01b0\\u1edbc c\\u1ed1t d\\u1eeba chu\\u1ea9n v\\u1ecb mi\\u1ec1n T\\u00e2y. Sau khi \\u0103n tr\\u01b0a, \\u0111o\\u00e0n n\\u1eb1m v\\u00f5ng ngh\\u1ec9 ng\\u01a1i, tham quan tr\\u1ea1i nu\\u00f4i c\\u00e1 s\\u1ea5u, nh\\u00edm, \\u1ebfch\\u2026 v\\u00e0 \\u0111i xe \\u0111\\u1ea1p quanh v\\u01b0\\u1eddn d\\u1eeba. Ngo\\u00e0i ra, Qu\\u00fd kh\\u00e1ch c\\u00f3 th\\u1ec3 tham gia c\\u00e1c tr\\u00f2 ch\\u01a1i d\\u00e2n gian nh\\u01b0: \\u0111u d\\u00e2y, ch\\u1ea1y xe \\u0111\\u1ea1p m\\u1ea1o hi\\u1ec3m qua v\\u00e1n, \\u0111ua xu\\u1ed3ng ch\\u00e8o tr\\u00ean h\\u1ed3, nh\\u1ea3y xa. Tr\\u1edf v\\u1ec1 \\u0111\\u1ea5t li\\u1ec1n, Qu\\u00fd kh\\u00e1ch kh\\u1edfi h\\u00e0nh \\u0111i C\\u1ea7n Th\\u01a1 theo 2 tuy\\u1ebfn cao t\\u1ed1c Trung L\\u01b0\\u01a1ng - M\\u1ef9 Thu\\u1eadn v\\u00e0 M\\u1ef9 Thu\\u1eadn - C\\u1ea7n Th\\u01a1; Chi\\u00eam ng\\u01b0\\u1ee1ng c\\u1ea7u M\\u1ef9 Thu\\u1eadn 2 - D\\u1ef1 \\u00e1n tr\\u1ecdng \\u0111i\\u1ec3m qu\\u1ed1c gia c\\u00f3 chi\\u1ec1u d\\u00e0i 1,9km n\\u1ed1i li\\u1ec1n t\\u1ec9nh V\\u0129nh Long v\\u00e0 Ti\\u1ec1n Giang. Sau khi d\\u00f9ng b\\u1eefa t\\u1ed1i t\\u1ea1i th\\u00e0nh ph\\u1ed1 C\\u1ea7n Th\\u01a1, Qu\\u00fd kh\\u00e1ch t\\u1ef1 do d\\u1ea1o ph\\u1ed1 \\u0111\\u00eam kh\\u00e1m ph\\u00e1 \\u201cT\\u00e2y \\u0110\\u00f4\\u201d lung linh s\\u1eafc m\\u00e0u: ng\\u1eafm c\\u1ea3nh c\\u1ea7u C\\u1ea7n Th\\u01a1 v\\u1ec1 \\u0111\\u00eam, check-in c\\u1ea7u T\\u00ecnh Y\\u00eau - Thi\\u1ebft k\\u1ebf u\\u1ed1n l\\u01b0\\u1ee3n h\\u00ecnh ch\\u1eef S c\\u00f9ng hai \\u0111\\u00e0i sen v\\u00e0 h\\u1ec7 th\\u1ed1ng \\u0111\\u00e8n led r\\u1ef1c r\\u1ee1 s\\u1eafc m\\u00e0u.<\\/p>\"},{\"title\":\"Ng\\u00e0y 2: C\\u1ea7n Th\\u01a1 \\u2013 Ch\\u1ee3 N\\u1ed5i C\\u00e1i R\\u0103ng \\u2013 M\\u1ef9 Kh\\u00e1nh \\u2013 TP.H\\u1ed3 Ch\\u00ed Minh\",\"content\":\"<p>\\u0110o\\u00e0n tr\\u1ea3 ph\\u00f2ng v\\u00e0 kh\\u1edfi h\\u00e0nh ra B\\u1ebfn Ninh Ki\\u1ec1u, xu\\u1ed1ng thuy\\u1ec1n du ngo\\u1ea1n tr\\u00ean s\\u00f4ng C\\u1ea7n Th\\u01a1, nghe gi\\u1edbi thi\\u1ec7u v\\u1ec1 ch\\u1ee3 th\\u1ee7y s\\u1ea3n n\\u01b0\\u1edbc ng\\u1ecdt C\\u1ea7n Th\\u01a1; tr\\u1ea3i nghi\\u1ec7m ch\\u1ee3 n\\u1ed5i C\\u00e1i R\\u0103ng - m\\u1ed9t h\\u00ecnh th\\u1ee9c h\\u1ecdp ch\\u1ee3 \\u0111\\u1eb7c tr\\u01b0ng t\\u1ea1i c\\u00e1c ng\\u00e3 s\\u00f4ng c\\u1ee7a v\\u00f9ng \\u0111\\u1ed3ng b\\u1eb1ng s\\u00f4ng C\\u1eedu Long \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c c\\u00f4ng nh\\u1eadn Di S\\u1ea3n V\\u0103n H\\u00f3a Phi V\\u1eadt Th\\u1ec3 Qu\\u1ed1c Gia.&nbsp;<\\/p><p>Ti\\u1ebfp t\\u1ee5c, Qu\\u00fd kh\\u00e1ch tham quan:&nbsp;<\\/p><ul><li>L\\u00e0ng du l\\u1ecbch M\\u1ef9 Kh\\u00e1nh - \\u0111i\\u1ec3m du l\\u1ecbch sinh th\\u00e1i h\\u1ea5p d\\u1eabn v\\u1edbi c\\u00e1c \\u0111i\\u1ec3m tham quan Nh\\u00e0 c\\u1ed5 Nam b\\u1ed9 h\\u01a1n 115 n\\u0103m tu\\u1ed5i; v\\u01b0\\u1eddn hoa M\\u1ef9 Kh\\u00e1nh; khu nh\\u00e0 v\\u0103n ho\\u00e1 4 d\\u00e2n t\\u1ed9c Kinh - Hoa - Ch\\u0103m - Khmer; l\\u00e0ng ngh\\u1ec1 truy\\u1ec1n th\\u1ed1ng...&nbsp;<\\/li><li>Th\\u01b0\\u1edfng th\\u1ee9c c\\u00e1c lo\\u1ea1i tr\\u00e1i c\\u00e2y t\\u01b0\\u01a1i theo m\\u00f9a v\\u00e0 nghe \\u0111\\u1eddn ca t\\u00e0i t\\u1eed Nam B\\u1ed9&nbsp;<\\/li><li>Tr\\u1ea3i nghi\\u1ec7m tr\\u00f2 ch\\u01a1i Th\\u1ea3m tr\\u01b0\\u1ee3t C\\u1ea7u v\\u1ed3ng - chinh ph\\u1ee5c c\\u1ea7u tr\\u01b0\\u1ee3t phao kh\\u00f4 \\u0111\\u1ea7u ti\\u00ean c\\u1ee7a mi\\u1ec1n T\\u00e2y v\\u1edbi \\u0111\\u1ed9 cao 20m, \\u0111\\u01b0\\u1eddng tr\\u01b0\\u1ee3t d\\u00e0i 160m (chi ph\\u00ed t\\u1ef1 t\\u00fac)&nbsp;<\\/li><li>Thi\\u1ec1n Vi\\u1ec7n Ph\\u01b0\\u01a1ng Nam - m\\u1ed9t trong nh\\u1eefng ng\\u00f4i thi\\u1ec1n vi\\u1ec7n r\\u1ed9ng nh\\u1ea5t \\u0110\\u1ed3ng b\\u1eb1ng s\\u00f4ng C\\u1eedu Long, tham quan l\\u1ea7u tr\\u1ed1ng, l\\u1ea7u chu\\u00f4ng, l\\u1ec5 Ph\\u1eadt t\\u1ea1i ch\\u00e1nh \\u0111i\\u1ec7n.&nbsp;<\\/li><li>Sau khi d\\u1eebng ch\\u00e2n tham quan v\\u00e0 mua s\\u1eafm t\\u1ea1i si\\u00eau th\\u1ecb \\u0111\\u1eb7c s\\u1ea3n v\\u00e0 qu\\u00e0 l\\u01b0u ni\\u1ec7m H\\u01b0\\u01a1ng \\u0110\\u1ea3o, \\u0111o\\u00e0n kh\\u1edfi h\\u00e0nh v\\u1ec1 th\\u00e0nh ph\\u1ed1 H\\u1ed3 Ch\\u00ed Minh, k\\u1ebft th\\u00fac ch\\u01b0\\u01a1ng tr\\u00ecnh du l\\u1ecbch t\\u1ea1i \\u0111i\\u1ec3m \\u0111\\u00f3n ban \\u0111\\u1ea7u.&nbsp;<\\/li><\\/ul><p><span style=\\\"color:hsl(0, 75%, 60%);\\\"><i><strong>L\\u01b0u \\u00fd: Ch\\u01b0\\u01a1ng tr\\u00ecnh c\\u1ee7a Vietravel l\\u00e0 ch\\u01b0\\u01a1ng tr\\u00ecnh tr\\u1ecdn g\\u00f3i, kh\\u00f4ng \\u0111\\u01b0\\u1ee3c \\u00e1p d\\u1ee5ng ch\\u00ednh s\\u00e1ch mi\\u1ec5n gi\\u1ea3m, \\u01b0u ti\\u00ean v\\u00e0o \\u0111i\\u1ec3m tham quan (n\\u1ebfu c\\u00f3) d\\u00e0nh cho tr\\u1ebb em, ng\\u01b0\\u1eddi cao tu\\u1ed5i, ng\\u01b0\\u1eddi c\\u00f3 c\\u00f4ng v\\u1edbi c\\u00e1ch m\\u1ea1ng v\\u00ec v\\u1eady Vietravel s\\u1ebd kh\\u00f4ng ho\\u00e0n l\\u1ea1i ph\\u1ea7n ch\\u00eanh l\\u1ec7ch cho c\\u00e1c kh\\u00e1ch h\\u00e0ng thu\\u1ed9c di\\u1ec7n \\u01b0u ti\\u00ean n\\u00e0y. B\\u1eefa \\u0103n t\\u1ed1i tr\\u00ean Du Thuy\\u1ec1n C\\u1ea7n Th\\u01a1 ph\\u1ee5 thu\\u1ed9c v\\u00e0o l\\u1ecbch ho\\u1ea1t \\u0111\\u1ed9ng c\\u1ee7a Du Thuy\\u1ec1n n\\u00ean c\\u00f3 th\\u1ec3 linh \\u0111\\u1ed9ng \\u0111i\\u1ec1u ch\\u1ec9nh chuy\\u1ec3n v\\u1ec1 \\u0103n tr\\u00ean \\u0111\\u1ea5t li\\u1ec1n \\u0111\\u1ec3 ph\\u00f9 h\\u1ee3p v\\u1edbi t\\u00ecnh h\\u00ecnh th\\u1ef1c t\\u1ebf.<\\/strong><\\/i><\\/span><\\/p>\"}]', '/userfiles/images/tours/cantho/tfd_241016015241_388517_SONG%20BA%20LAI.jpg', NULL, 'tour-my-tho-con-thoi-son-ben-tre-can-tho-cho-noi-cai-rang-my-khanh', NULL, NULL, NULL, '2025-09-10 04:14:44', '2025-09-10 04:14:44');
